sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
layout(color) uniform half4 tint;
half4 effectMain(float2 coord){float2 p=coord*scale;float n=sin(p.x*6.0+phase)+cos(p.y*7.0-phase*1.3);float2 d=float2(cos(p.y*8.0),sin(p.x*8.0))*n*amount*4.0;half4 c=image.eval(coord-d);return half4(mix(c.rgb,c.rgb*tint.rgb,half(0.15)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
